from collections import deque
seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if grid[r][c]==0 and (r,c) not in seen:
   q=[(r,c)];seen.add((r,c)); comp=[]
   while q:
    x,y=q.pop();comp.append((x,y))
    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
     xx,yy=x+dx,y+dy
     if 0<=xx<R and 0<=yy<C and grid[xx][yy]==0 and (xx,yy) not in seen:
      seen.add((xx,yy));q.append((xx,yy))
   comps.append(comp)
print(sorted([(len(x),x[:10]) for x in comps],reverse=True))

out=[r[:] for r in grid]
for comp in comps:
 if len(comp)<10:
  for r,c in comp:
   for dr in [-1,0,1]:
    for dc in [-1,0,1]:
     rr,cc=r+dr,c+dc
     if 0<=rr<R and 0<=cc<C and grid[rr][cc]==1:out[rr][cc]=7
print('\n'.join(' '.join(map(str,r)) for r in out))

